import { stopPropagation } from '@newgrand/udp-ui/es/functionalComponent/table/util';
import Handsontable from 'handsontable';
import {
  getBorderByDirection,
  getRenderCellProperties,
  isInFrozen,
  optimizeRender,
  renderCellReactRoot,
  resetCellRenderStyle,
  resetSkippedCellRender,
  setIsLastTreeChildren
} from '../utils';
import './style.less';
import { TreeLine } from './treeExpandLine';
import { toggleTreeNode } from './utils';

export default function treeRender(
  this: Handsontable.Core,
  instance: Handsontable.Core,
  TD: any,
  row: number,
  col: number,
  prop: string | number,
  value: any,
  cellProperties: Handsontable.CellProperties
) {
  const renderCellProperties = getRenderCellProperties(instance, row, col, cellProperties);
  if (!renderCellProperties) {
    resetSkippedCellRender(TD, row, col);
    return;
  }
  cellProperties = renderCellProperties;
  row = cellProperties.row;
  col = cellProperties.col;
  resetCellRenderStyle(TD, row, col);
  const isNewRoot = optimizeRender(TD, row, col, isInFrozen(row, col, cellProperties, instance));

  setIsLastTreeChildren(cellProperties, instance);

  TD.className = cellProperties.className;
  TD.classList.remove('htMiddle');
  TD.classList.remove('htBottom');

  let totalHeight = 0;
  for (let i = 0; i < (cellProperties.rowspan || 1); i++) {
    const rowHeight = instance.getRowHeight(row + i);
    totalHeight += rowHeight;
  }
  let totalWidth = 0;
  for (let i = 0; i < (cellProperties.colspan || 1); i++) {
    const colWidth = instance.getColWidth(col + i);
    totalWidth += colWidth;
  }

  if (cellProperties?.cellBorders) {
    for (const direction in cellProperties?.cellBorders) {
      if (Object.prototype.hasOwnProperty.call(cellProperties?.cellBorders, direction)) {
        const border = cellProperties?.cellBorders[direction];
        if (!border.hide) {
          getBorderByDirection(direction, border, TD);
        }
      }
    }
  }

  TD.style.padding = 0;

  const rootKey = `root-${row}_${col}`;
  const root = TD[rootKey];
  renderCellReactRoot(
    root,
    <TreeComponent hot={instance} cellProperties={cellProperties} width={totalWidth - 2} height={totalHeight - 2} />,
    isNewRoot && row === 0,
    () => TD[rootKey] === root
  );
}

const TreeComponent = ({
  hot,
  width,
  height,
  cellProperties
}: {
  width: number;
  height: number;
  cellProperties: Handsontable.CellProperties;
  hot: Handsontable.Core;
}) => {
  const { row, col, children, treeLevel = 1, formatData, expanded = false, isLast } = cellProperties;

  const switchExpand = (e) => {
    stopPropagation(e);
    toggleTreeNode(hot, row, col);
  };

  return (
    <div className="treeHeader" style={{ width, height }}>
      <TreeLine treeLevel={treeLevel} isLast={isLast} />
      <span
        className={`row-expand-icon ${isLast && children?.length === 0 ? 'row-expand-icon-last' : ''}`}
        onClick={children?.length > 0 ? switchExpand : undefined}
      >
        {children?.length > 0 ? <span className={`icon ${expanded ? ' icon-expanded' : 'icon-collapsed'}`} /> : null}
      </span>
      <span style={{ marginLeft: '4px' }}>{formatData}</span>
    </div>
  );
};

