import { HotChartRender } from '@/components/report/design/components/customTable/plugins/chartRender/render';
import Handsontable from 'handsontable';
import {
  getBorderByDirection,
  getRenderCellProperties,
  optimizeRender,
  resetCellRenderStyle,
  resetSkippedCellRender
} from '../utils';

export default function chartRender(
  this: Handsontable.Core,
  instance: Handsontable.Core,
  TD: HTMLTableCellElement,
  row: number,
  col: number,
  prop: string | number,
  value: any,
  cellProperties: Handsontable.CellProperties
) {
  const renderCellProperties = getRenderCellProperties(instance, row, col, cellProperties);
  if (!renderCellProperties) {
    resetSkippedCellRender(TD, row, col);
    return;
  }
  cellProperties = renderCellProperties;
  row = cellProperties.row;
  col = cellProperties.col;
  resetCellRenderStyle(TD, row, col);
  optimizeRender(TD, row, col, true);

  if (cellProperties?.cellBorders) {
    for (const direction in cellProperties?.cellBorders) {
      if (Object.prototype.hasOwnProperty.call(cellProperties?.cellBorders, direction)) {
        const border = cellProperties?.cellBorders[direction];
        if (!border.hide) {
          getBorderByDirection(direction, border, TD);
        }
      }
    }
  }

  const data = JSON.parse(cellProperties.formatData || '[]');
  cellProperties.editor = false;
  cellProperties.chartStyle.graphType = cellProperties.chartConfig.graphType;
  // chart 里会覆盖 TD 的 className
  cellProperties.className = TD.classList.value ?? '';

  HotChartRender(
    instance,
    TD,
    row,
    col,
    cellProperties,
    cellProperties.chartType,
    data,
    cellProperties.chartConfig,
    cellProperties.chartStyle
  );
}

