import assert from 'node:assert/strict';

import { createVirtualizedMergeCellsSettings } from '../src/components/report/preview/tableSheets/mergeVirtualization';

const mergeCells = [
  { row: 29, col: 2, rowspan: 40, colspan: 3 },
  { row: 69, col: 2, rowspan: 40, colspan: 3 }
];

const settings = createVirtualizedMergeCellsSettings(mergeCells);

assert.equal(settings.virtualized, true, 'merged-cell viewport virtualization must stay enabled');
assert.equal(settings.cells, mergeCells, 'logical merge definitions must be passed through without physical splitting');
assert.deepEqual(settings.cells, [
  { row: 29, col: 2, rowspan: 40, colspan: 3 },
  { row: 69, col: 2, rowspan: 40, colspan: 3 }
]);

const emptySettings = createVirtualizedMergeCellsSettings();
assert.deepEqual(emptySettings, { virtualized: true, cells: [] });
assert.notEqual(
  emptySettings.cells,
  createVirtualizedMergeCellsSettings().cells,
  'empty settings calls must not share a mutable cells array'
);

console.log('preview merge virtualization tests passed');

