import assert from 'node:assert/strict';

import { getCellRootKey, releaseCellReactRoots } from '../src/components/report/preview/plugins/cellRootLifecycle';
import { SharedRuleRegistry } from '../src/components/report/preview/tableSheets/styleSheetRegistry';

function createRoot() {
  return {
    unmountCount: 0,
    unmount() {
      this.unmountCount += 1;
    }
  };
}

const firstRoot = createRoot();
const secondRoot = createRoot();
const cell = {
  [getCellRootKey(1, 2)]: firstRoot,
  [getCellRootKey(3, 4)]: secondRoot,
  unrelated: true
};

releaseCellReactRoots(cell, getCellRootKey(3, 4));
assert.equal(firstRoot.unmountCount, 1, 'roots belonging to recycled coordinates must be unmounted');
assert.equal(secondRoot.unmountCount, 0, 'the reusable root must remain mounted');
assert.equal(cell[getCellRootKey(1, 2)], undefined);
assert.equal(cell[getCellRootKey(3, 4)], secondRoot);
assert.equal(cell.unrelated, true);

releaseCellReactRoots(cell);
assert.equal(secondRoot.unmountCount, 1, 'remaining roots must be unmounted during cell cleanup');
assert.equal(cell[getCellRootKey(3, 4)], undefined);

const appliedRuleSets: string[][] = [];
const registry = new SharedRuleRegistry((rules) => appliedRuleSets.push(rules));
const firstOwner = {};
const secondOwner = {};

registry.sync(firstOwner, ['.shared { color: red; }', '.first { color: blue; }']);
registry.sync(secondOwner, ['.shared { color: red; }', '.second { color: green; }']);
assert.deepEqual(registry.getRules(), [
  '.shared { color: red; }',
  '.first { color: blue; }',
  '.second { color: green; }'
]);

registry.release(firstOwner);
assert.deepEqual(
  registry.getRules(),
  ['.shared { color: red; }', '.second { color: green; }'],
  'shared rules must remain while another report instance uses them'
);

registry.release(secondOwner);
assert.deepEqual(registry.getRules(), [], 'the last owner must release all of its dynamic rules');
assert.deepEqual(appliedRuleSets.at(-1), []);

console.log('preview resource lifecycle tests passed');

